import {
  getAccount,
  getHtml,
  getJson,
  getJsonBySearchId,
  getLocations,
} from "serpapi";
import { z } from "zod";
import { tool } from "@/lib/observability";

const serpEnvSchema = z.object({
  apiKey: z.string().min(1, "SERPAPI_API_KEY is required"),
  timeout: z.coerce.number().int().positive().optional(),
});

const serpSearchParamsSchema = z
  .looseObject({
    engine: z.string().min(1).default("google"),
    q: z.string().min(1).optional(),
    location: z.string().min(1).optional(),
    hl: z.string().min(1).optional(),
    gl: z.string().min(2).max(5).optional(),
    google_domain: z.string().min(1).optional(),
    start: z.number().int().min(0).optional(),
    num: z.number().int().min(1).max(100).optional(),
    device: z.enum(["desktop", "tablet", "mobile"]).optional(),
    safe: z.enum(["active", "off"]).optional(),
    async: z.boolean().optional(),
    timeout: z.number().int().positive().optional(),
  })
  .refine(
    (params) =>
      Boolean(params.q) ||
      Object.keys(params).some((key) => key !== "engine" && key !== "timeout"),
    {
      message: "Provide a query (q) or engine-specific search parameters",
      path: ["q"],
    },
  );

const serpSearchIdSchema = z.string().min(1, "searchId is required");

const serpLocationsParamsSchema = z.object({
  q: z.string().min(1).optional(),
  limit: z.number().int().positive().max(1000).optional(),
});

export type SerpClientOptions = {
  apiKey?: string;
  timeout?: number;
};

export type SerpSearchParams = z.input<typeof serpSearchParamsSchema>;
export type SerpLocationsParams = z.input<typeof serpLocationsParamsSchema>;

export function createSerpClient(options: SerpClientOptions = {}) {
  let credentials: z.output<typeof serpEnvSchema> | undefined;

  const resolveCredentials = () => {
    credentials ??= serpEnvSchema.parse({
      apiKey: options.apiKey ?? process.env.SERPAPI_API_KEY,
      timeout: options.timeout ?? process.env.SERPAPI_TIMEOUT_MS,
    });

    return credentials;
  };

  async function search<T = unknown>(
    params: SerpSearchParams & Record<string, unknown>,
    responseSchema?: z.ZodType<T>,
  ): Promise<T> {
    const { apiKey, timeout } = resolveCredentials();
    serpSearchParamsSchema.parse(params);
    const requestTimeout =
      typeof params.timeout === "number" ? params.timeout : timeout;
    const json = await getJson({
      ...params,
      api_key: apiKey,
      timeout: requestTimeout,
    });

    return responseSchema ? responseSchema.parse(json) : (json as T);
  }

  async function getBySearchId<T = unknown>(
    searchId: string,
    responseSchema?: z.ZodType<T>,
  ): Promise<T> {
    const { apiKey, timeout } = resolveCredentials();
    const json = await getJsonBySearchId(serpSearchIdSchema.parse(searchId), {
      api_key: apiKey,
      timeout,
    });

    return responseSchema ? responseSchema.parse(json) : (json as T);
  }

  return {
    search: tool("serp.search", search) as typeof search,

    getBySearchId: tool(
      "serp.getBySearchId",
      getBySearchId,
    ) as typeof getBySearchId,

    async searchHtml(params: SerpSearchParams): Promise<string> {
      const { apiKey, timeout } = resolveCredentials();
      const parsed = serpSearchParamsSchema.parse(params);

      return getHtml({
        ...parsed,
        api_key: apiKey,
        timeout: parsed.timeout ?? timeout,
      });
    },

    async account() {
      const { apiKey, timeout } = resolveCredentials();
      return getAccount({ api_key: apiKey, timeout });
    },

    async locations(params: SerpLocationsParams = {}) {
      return getLocations(serpLocationsParamsSchema.parse(params));
    },
  };
}

export const serpClient = createSerpClient();
import { Firecrawl } from "firecrawl";
import { z } from "zod";
import { tool } from "@/lib/observability";

const firecrawlEnvSchema = z.object({
  apiKey: z.string().min(1, "FIRECRAWL_API_KEY is required"),
});

const scrapeParamsSchema = z.object({
  url: z.url(),
  formats: z.array(z.enum(["markdown", "html"])).default(["markdown"]),
  onlyMainContent: z.boolean().default(true),
});

export type FirecrawlClientOptions = {
  apiKey?: string;
};

export type FirecrawlScrapeParams = z.input<typeof scrapeParamsSchema>;

export function createFirecrawlClient(options: FirecrawlClientOptions = {}) {
  let client: Firecrawl | undefined;

  const resolveClient = () => {
    if (client) {
      return client;
    }

    const { apiKey } = firecrawlEnvSchema.parse({
      apiKey: options.apiKey ?? process.env.FIRECRAWL_API_KEY,
    });

    client = new Firecrawl({ apiKey });
    return client;
  };

  async function scrape(params: FirecrawlScrapeParams) {
    const { url, formats, onlyMainContent } = scrapeParamsSchema.parse(params);

    return resolveClient().scrape(url, { formats, onlyMainContent });
  }

  return {
    scrape: tool("firecrawl.scrape", scrape),
  };
}

export const firecrawlClient = createFirecrawlClient();

