  if (typeof reported === "number" && Number.isFinite(reported) && reported >= 0) {
    return decision(Math.round(reported), "charged");
  }

  // Fallback — a document came back, even for a 403/404 page.
  let credits = FIRECRAWL_FALLBACK.perPage;
