  }
  record({
    provider: "firecrawl",
    operation: "scrape",
    decision: firecrawlScrapeCredits(response, options),
    httpStatus: 200,
    durationMs: Math.round(performance.now() - started),
    detail: { ...requestDetail, ...firecrawlResponseDetail(response) },
  });
  return response;
}

