for (const r of rows) console.log(JSON.stringify({ provider: r.provider, op: r.operation, user: r.userId ? "set" : null, runId: r.runId ? "set" : null, source: r.source, workflow: r.workflow, env: r.environment, credits: r.credits, billable: r.billable, reason: r.reason, http: r.httpStatus, ms: r.durationMs, detail: r.detail }));
const blob = JSON.stringify(rows);
console.log("leaks:", { apiKey: blob.includes(process.env.SERPAPI_API_KEY!) || blob.includes(process.env.FIRECRAWL_API_KEY!), query: blob.includes("nifty 50"), token: blob.includes("SECRET123") });
await prisma.$disconnect();
EOF
