                    </tr>
                  ) : (
                    users.rows.map((row, index) => (
                      <tr key={row.userId} className="border-t border-border/40">
                        <td className="py-2 pr-3 text-muted-foreground">
                          {(page - 1) * USERS_PAGE_SIZE + index + 1}
